write {"content": "import json, subprocess, datetime

def api(method, **params):
    data = {k: str(v) for k, v in params.items()}
    cmd = ["curl", "-sS", "-X", "POST", f"https://slack.com/api/{method}",
           "-H", "Authorization: Bearer <TOKEN>"]
    for k, v in data.items():
        cmd += ["--data-urlencode", f"{k}={v}"]
    out = subprocess.run(cmd, capture_output=True, text=True)
    if out.returncode != 0:
        raise RuntimeError(out.stderr)
    return json.loads(out.stdout)

cursor = None
channels = []
while True:
    params = dict(exclude_archived=True, limit=1000, user="UOBRCZJBAIG",
                  types="public_channel,private_channel")
    if cursor:
        params["cursor"] = cursor
    r = api("users.conversations", **params)
    if not r.get("ok"):
        print("ERROR", r)
        break
    channels += r.get("channels", [])
    cursor = r.get("response_metadata", {}).get("next_cursor")
    if not cursor:
        break

cutoff = 1772323200  # 2026-03-01 00:00:00 UTC
assert datetime.datetime.utcfromtimestamp(cutoff) == datetime.datetime(2026, 3, 1)
print("Victor's non-archived channels:", len(channels))
for c in channels:
    created = int(c.get("created", 0))
    dt = datetime.datetime.utcfromtimestamp(created).strftime("%Y-%m-%d")
    print(c["id"], "|", c.get("name"), "| private:", c.get("is_private"),
          "| created:", dt, "| before_2026-03:", created < cutoff)
